    sa.Column('mode', sa.String(length=20), nullable=False, comment="Model interface mode: 'chat' (conversational), 'embedding' (vector embeddings), 'completion' (text completion), 'responses' (structural), 'routing' (load-balancing group)"),
    sa.Column('parameters', sa.Float(), nullable=True, comment='Model size in billions of parameters'),
    sa.Column('tags', sa.JSON(), nullable=True, comment='Tags for filtering (cost, speed, capabilities, use cases)'),
