    sa.Column('api_url', sa.String(length=500), nullable=True, comment='Custom API URL for deployments like Azure, Bedrock, Ollama. Leave empty for standard providers (the standard URL is used).'),
    sa.Column('auth_type', sa.String(length=50), nullable=True),
    sa.Column('api_key', sa.Text(), nullable=True),
    sa.Column('provider_config', sa.Text(), nullable=True),
    sa.Column('default_temperature', sa.Float(), nullable=True, comment='Sampling temperature (0-2)'),
    sa.Column('default_max_tokens', sa.Integer(), nullable=True, comment='Maximum tokens to generate'),
    sa.Column('system_prompt', sa.Text(), nullable=True, comment="\n        Default system prompt to prepend to all completion requests.\n        This is inserted as the first message with role='system'.\n        Can be overridden on a per-request basis.\n        Typical size: 500-10,000 characters. Supports up to 1GB in PostgreSQL TEXT.\n        "),
    sa.Column('top_p', sa.Float(), nullable=True, comment='Nucleus sampling threshold (0-1). Alternative to temperature'),
    sa.Column('n', sa.Integer(), nullable=True, comment='Number of completions to generate per request'),
    sa.Column('stop_sequences', sa.JSON(), nullable=True, comment='List of sequences where API will stop generating (max 4)'),
    sa.Column('seed', sa.Integer(), nullable=True, comment='Seed for deterministic sampling (reproducibility)'),
    sa.Column('presence_penalty', sa.Float(), nullable=True, comment='Penalize new tokens based on presence in text (-2.0 to 2.0)'),
    sa.Column('frequency_penalty', sa.Float(), nullable=True, comment='Penalize new tokens based on frequency in text (-2.0 to 2.0)'),
    sa.Column('logit_bias', sa.JSON(), nullable=True, comment='Modify probability of specific tokens (token_id: bias_value)'),
    sa.Column('response_format', sa.JSON(), nullable=True, comment='Force response format, e.g. {"type": "json_object"} for JSON mode'),
    sa.Column('logprobs', sa.Boolean(), nullable=True, comment='Return log probabilities of output tokens'),
    sa.Column('top_logprobs', sa.Integer(), nullable=True, comment='Number of most likely tokens to return with logprobs (0-5)'),
    sa.Column('stream_options', sa.JSON(), nullable=True, comment='Streaming options, e.g. {"include_usage": true}'),
    sa.Column('supports_streaming', sa.Boolean(), nullable=True),
    sa.Column('supports_function_calling', sa.Boolean(), nullable=True),
    sa.Column('supports_vision', sa.Boolean(), nullable=True),
    sa.Column('supports_batch', sa.Boolean(), nullable=True),
    sa.Column('tools', sa.JSON(), nullable=True, comment='List of tools/functions the model can call'),
    sa.Column('tool_choice', sa.String(length=50), nullable=True, comment="Tool choice strategy: 'none', 'auto', 'required', or specific function"),
    sa.Column('parallel_tool_calls', sa.Boolean(), nullable=True, comment='Enable parallel function calling (OpenAI default: true)'),
    sa.Column('user_identifier', sa.String(length=255), nullable=True, comment='Unique identifier for end-user (for abuse monitoring)'),
    sa.Column('api_version', sa.String(length=50), nullable=True, comment='API version (Azure, Bedrock, etc.)'),
    sa.Column('extra_headers', sa.JSON(), nullable=True, comment='Additional headers to send with requests'),
    sa.Column('fallback_models', postgresql.JSONB(astext_type=sa.Text()), nullable=True, comment="Model-level failover chain: ordered list of model ids to try, in order, when this model's own call fails with a retryable error."),
    sa.Column('model_metadata', sa.JSON(), nullable=True, comment='Custom metadata for logging/tracking (sent to logging integrations)'),
    sa.Column('drop_params', sa.Boolean(), server_default=sa.text('true'), nullable=True, comment="Apply the provider's dropped-parameters list (unset reads as on)"),
    sa.Column('additional_drop_params', sa.JSON(), nullable=True, comment="List of specific parameter names to drop for this model (e.g. ['top_p', 'presence_penalty']). Used when drop_params=False to selectively remove known unsupported parameters before sending to provider."),
    sa.Column('thinking_enabled', sa.Boolean(), server_default=sa.text('false'), nullable=False, comment="Enable extended-thinking / reasoning mode by default for this model. Generic switch translated by the proxy adapter into the provider's specific parameter at request time: Anthropic adds `thinking: {type: 'enabled', budget_tokens: ...}` (and forces temperature to 1.0); OpenAI o-series sets `reasoning_effort` and strips temperature/top_p; Google Gemini 2.5 Thinking adds `thinking_config: {thinking_budget: ...}`. Only meaningful for models that actually support reasoning — flipping it on for a non-reasoning model is a no-op at the adapter level."),
    sa.Column('routing_weight', sa.Integer(), nullable=True, comment='Weight for load balancing (higher = more traffic)'),
    sa.Column('rate_limit_rpm', sa.Integer(), nullable=True, comment='Requests per minute limit'),
    sa.Column('rate_limit_tpm', sa.Integer(), nullable=True, comment='Tokens per minute limit'),
