    sa.Column('cost_per_input_token', sa.Float(), nullable=True, comment='USD per 1M input tokens'),
    sa.Column('cost_per_output_token', sa.Float(), nullable=True, comment='USD per 1M output tokens'),
    sa.Column('cost_per_image', sa.Float(), nullable=True, comment='USD cost per generated image. Used for image-mode models. Distinct from cost_per_input_token / cost_per_output_token so per-image and per-token spend roll up cleanly. Stored as DOUBLE PRECISION (matches the rest of the cost columns); 8 bytes is plenty for sub-cent precision USD.'),
    sa.Column('supported_image_sizes', postgresql.JSONB(astext_type=sa.Text()), nullable=True, comment='Whitelist of accepted image sizes for image-mode models, e.g. ["1024x1024","1024x1792","1792x1024"]. Enforced at the proxy edge.'),
    sa.Column('supported_image_qualities', postgresql.JSONB(astext_type=sa.Text()), nullable=True, comment='Whitelist of accepted quality tiers, e.g. ["standard","hd"]. Enforced at the proxy edge.'),
    sa.Column('max_images_per_request', sa.Integer(), server_default='1', nullable=False, comment='Maximum number of images permitted per single request (`n` parameter). DALL-E 3 = 1, DALL-E 2 = 10.'),
    sa.Column('cost_per_audio_char', sa.Float(), nullable=True, comment='USD per generated character (TTS).'),
    sa.Column('supported_voices', sa.JSON(), nullable=True, comment='Whitelist of accepted voice ids, e.g. ["alloy","echo","fable","onyx","nova","shimmer"].'),
    sa.Column('supported_audio_formats', sa.JSON(), nullable=True, comment='Whitelist of accepted output formats, e.g. ["mp3","opus","aac","flac","wav","pcm"].'),
    sa.Column('cost_per_audio_minute', sa.Float(), nullable=True, comment='USD per minute of input audio (STT). whisper-1 ~ 0.006.'),
    sa.Column('max_audio_duration_seconds', sa.Integer(), nullable=True, comment='Maximum input clip duration the proxy will accept. Mirrors provider caps.'),
    sa.Column('supported_input_formats', sa.JSON(), nullable=True, comment='Whitelist of accepted input formats, e.g. ["mp3","mp4","wav","m4a","webm"].'),
    sa.Column('supported_response_formats', postgresql.JSONB(astext_type=sa.Text()), nullable=True, comment='Response formats this model accepts upstream (STT today; pattern extends to image/video as needed). whisper-1 supports verbose_json (carries `duration` for cost calc) but gpt-4o-transcribe-family models reject it with a 400. NULL = whitelist not declared, proxy falls back to a model-name heuristic for one release cycle.'),
    sa.Column('cost_per_video_second', sa.Float(), nullable=True, comment='USD per second of generated video. Luma Dream Machine ~ 0.07.'),
    sa.Column('supported_video_resolutions', sa.JSON(), nullable=True, comment='Whitelist of accepted resolutions, e.g. ["720p","1080p"].'),
    sa.Column('supported_video_durations', sa.JSON(), nullable=True, comment='Whitelist of accepted clip durations in seconds, e.g. [5, 10].'),
    sa.Column('max_video_duration_seconds', sa.Integer(), nullable=True, comment='Hard ceiling on a single clip in seconds.'),
    sa.Column('timeout', sa.Float(), nullable=True, comment='Request timeout (seconds) bounding each upstream attempt (proxy default 120s).'),
    sa.Column('max_concurrent_requests', sa.Integer(), nullable=True, comment='Max simultaneous in-flight requests to this model. Enforced by a per-model semaphore in the Rust proxy. NULL = unbounded (honour only rate-limit rpm/tpm).'),
    sa.Column('allowed_fails', sa.Integer(), nullable=True, comment='Circuit-breaker failure threshold: open the breaker after this many consecutive failures.'),
    sa.Column('cooldown_time', sa.Integer(), nullable=True, comment='Circuit-breaker cooldown (seconds): how long the breaker stays open / Retry-After before half-open retry.'),
    sa.Column('enabled', sa.Boolean(), nullable=True, comment='Whether this model is enabled'),
    sa.Column('tenant_limits', sa.JSON(none_as_null=True), nullable=True, comment='Tenant-wide default LLM usage limits (throughput/concurrency/budget/tokens/requests); min-wins with RG.'),
    sa.Column('tenant_governance', sa.JSON(none_as_null=True), nullable=True, comment='Tenant-wide default LLM governance/policy (param caps, residency, guardrails); min-wins with RG.'),
