    sa.Column('retirement_announced_at', sa.Date(), nullable=True, comment="Date the provider announced the retirement. Informational — surfaced in the admin UI as 'announced N days ago' context, useful when judging whether downstream users have had reasonable notice."),
    sa.Column('retirement_reminder_date', sa.Date(), nullable=True, comment='Date from which the operator alert should start firing. Defaults to retire_date - 14 days at write time but is stored explicitly so operators can lengthen the lead time for business-critical models.'),
    sa.Column('retirement_replacement_model_name', sa.String(length=255), nullable=True, comment='Provider-side model name of the recommended successor. Free-form string rather than an FK so cross-provider replacements work (e.g. DALL-E 3 → FLUX 1.1 Pro on Replicate). Admin UI autocompletes against existing llm_model rows but allows free entry.'),
    sa.Column('retirement_replacement_provider_key', sa.String(length=100), nullable=True, comment='Provider key of the replacement (`openai`, `anthropic`, `fal_ai`, ...). Null when the replacement is on the same provider as the retiring model. Drives the cross-link from the retirement banner to the replacement model row in the admin UI.'),
    sa.Column('retirement_notes', sa.Text(), nullable=True, comment="Free-form markdown. Recommended content: link to the provider's announcement, breaking-change summary, any migration notes operators should know about (different pricing tier, different output format, etc)."),
    sa.Column('capabilities', sa.JSON(), nullable=True, comment='Additional capabilities and metadata'),
