    sa.Column('server_id', sa.String(length=255), nullable=True),
    sa.Column('virtual_server_id', sa.String(length=255), nullable=True),
    sa.Column('server_url', sa.Text(), nullable=True),
    sa.Column('http_method', sa.String(length=10), nullable=False),
    sa.Column('endpoint', sa.Text(), nullable=True),
    sa.Column('endpoint_category', sa.String(length=50), nullable=True),
    sa.Column('total_duration_ms', sa.Float(), nullable=False),
    sa.Column('connect_time_ms', sa.Float(), nullable=True),
    sa.Column('handshake_time_ms', sa.Float(), nullable=True),
    sa.Column('processing_time_ms', sa.Float(), nullable=True),
    sa.Column('response_time_ms', sa.Float(), nullable=True),
    sa.Column('request_size_bytes', sa.Integer(), nullable=True),
