    sa.Column('llm_data', sa.JSON(), nullable=True, comment='LLM-specific data: provider, model_requested, model_used, prompt_tokens, completion_tokens, total_tokens, estimated_cost_usd, temperature, max_tokens, streaming, function_calling'),
    sa.Column('oauth_data', sa.JSON(), nullable=True, comment='OAuth-specific data: idp_id, flow_type, grant_type, scope, token_type'),
    sa.Column('virtual_mcp_data', sa.JSON(), nullable=True, comment='Virtual MCP-specific data: source_servers, aggregated_capabilities'),
    sa.Column('skill_data', sa.JSON(), nullable=True, comment='Skill-specific metrics data (same pattern as mcp_data, llm_data, etc.):\n        {\n            "skill_id": "skill-01J...",\n            "skill_name": "query-sales-data",\n            "skill_version": "1.0.0",\n            "execution_id": "ase-01J...",\n            "step_name": "query_data",\n            "is_dependency": false\n        }'),
    sa.Column('dns_resolution_time_ms', sa.Float(), nullable=True),
    sa.Column('ssl_handshake_time_ms', sa.Float(), nullable=True),
    sa.Column('tcp_connect_time_ms', sa.Float(), nullable=True),
    sa.Column('server_response_headers', sa.Text(), nullable=True),
    sa.Column('cache_hit', sa.Boolean(), nullable=True),
    sa.Column('rate_limited', sa.Boolean(), nullable=True),
    sa.Column('authentication_time_ms', sa.Float(), nullable=True),
